      SUBROUTINE RDPARS(KPARA,LPARA,IEP)C---- READ KEYWORD OF GIVEN ELEMENT FOR PARAMETER REFERENCEC---------------------------------------------------------------------      CHARACTER*15    KPARAC---------------------------------------------------------------------      INCLUDE 'TRNSPRT_PARAM.CIN'      INCLUDE 'DBEAM.CIN'      INCLUDE 'DBEND.CIN'      INCLUDE 'DCENT.CIN'      INCLUDE 'DCVTY.CIN'      INCLUDE 'DDRFT.CIN'      INCLUDE 'DETA.CIN'      INCLUDE 'DFIT.CIN'      INCLUDE 'DHKICK.CIN'      INCLUDE 'DKICK.CIN'      INCLUDE 'DMIS.CIN'      INCLUDE 'DOCT.CIN'      INCLUDE 'DPLT.CIN'      INCLUDE 'DQUAD.CIN'      INCLUDE 'DRAN.CIN'      INCLUDE 'DRBND.CIN'      INCLUDE 'DROT.CIN'      INCLUDE 'DSECT.CIN'      INCLUDE 'DSEXT.CIN'      INCLUDE 'DSHIFT.CIN'      INCLUDE 'DSOLE.CIN'      INCLUDE 'DSPEC.CIN'      INCLUDE 'DSROT.CIN'      INCLUDE 'DUPD.CIN'      INCLUDE 'NELMS.CIN'      INCLUDE 'NELMEQ.CIN'      INCLUDE 'PARDAT.CIN'      INCLUDE 'RDWRDS.CIN'C---------------------------------------------------------------------C      GO TO ( 100, 200, 300, 400, 500, 600, 700, 800,5000,1000,     1       1100,1200,5000,1400,5000,1600,5000,1800,1900,2000,     2       5000,5000,5000,2400,2500,2600,2700,2800,2800,5000,     3       5000,5000,5000,3400,3500,3500,5000,3800,5000,5000,     4       5000,4200,4300), NTYPE                                             C  100 CALL RDLOOK(KPARA,LPARA,DBEAM,1,NBEAM,IEP)      GO TO 5000C  200 CALL RDLOOK(KPARA,LPARA,DROT,1,NROT,IEP)      GO TO 5000C  300 CALL RDLOOK(KPARA,LPARA,DDRFT,1,NDRFT,IEP)      GO TO 5000C  400 CALL RDLOOK(KPARA,LPARA,DBEND,1,NBEND,IEP)      GO TO 5000C  500 CALL RDLOOK(KPARA,LPARA,DQUAD,1,NQUAD,IEP)      GO TO 5000C  600 CALL RDLOOK(KPARA,LPARA,DUPD,1,NUPD,IEP)      GO TO 5000C  700 CALL RDLOOK(KPARA,LPARA,DCENT,1,NCENT,IEP)      GO TO 5000C  800 CALL RDLOOK(KPARA,LPARA,DMIS,1,NMIS,IEP)      GO TO 5000C 1000 CALL RDLOOK(KPARA,LPARA,DFIT,1,NFIT,IEP)      GO TO 5000C 1100 CALL RDLOOK(KPARA,LPARA,DCVTY,1,NCVTY,IEP)      GO TO 5000C 1200 CALL FNCORR(KPARA,LPARA,IEP)      GO TO 5000C 1400 CALL FNMTX(KPARA,LPARA,IEP)      IEP = IPARM      GO TO 5000C 1600 CALL RDLOOK(KPARA,LPARA,DSPEC,1,NSPEC,IEP)      GO TO 5000C 1800 CALL RDLOOK(KPARA,LPARA,DSEXT,1,NSEXT,IEP)      GO TO 5000C 1900 CALL RDLOOK(KPARA,LPARA,DSOLE,1,NSOLE,IEP)      GO TO 5000C 2000 CALL RDLOOK(KPARA,LPARA,DSROT,1,NSROT,IEP)      GO TO 5000C 2400 CALL RDLOOK(KPARA,LPARA,DSECT,1,NSECT,IEP)      GO TO 5000C 2500 CALL RDLOOK(KPARA,LPARA,DOCT,1,NOCT,IEP)      GO TO 5000C 2600 CALL RDLOOK(KPARA,LPARA,DRAN,1,NRAN,IEP)      GO TO 5000C 2700 CALL RDLOOK(KPARA,LPARA,DETA,1,NETA,IEP)      GO TO 5000C 2800 CALL RDLOOK(KPARA,LPARA,DRBND,1,NRBND,IEP)      GO TO 5000C 3400 CALL RDLOOK(KPARA,LPARA,DQUAD,1,NQUAD,IEP)      GO TO 5000C 3500 CALL RDLOOK(KPARA,LPARA,DHKICK,1,NHKCK,IEP)      GO TO 5000C 3800 CALL RDLOOK(KPARA,LPARA,DPLT,1,NPLT,IEP)      GO TO 5000C 4200 CALL RDLOOK(KPARA,LPARA,DKICK,1,NKICK,IEP)      GO TO 5000C 4300 CALL RDLOOK(KPARA,LPARA,DSHIFT,1,NSHIFT,IEP)      GO TO 5000C 5000 CONTINUE      RETURN      END